local OperationRunner = require(script.Parent.Extensions.OperationRunner)

export type Type = IHost & {
	Init: () -> (),
}

local Host = {}
Host.__index = Host

function Host.new(coreHost: IHost): IHost
	print("创建唐僧主机")
	local self = setmetatable({}, Host)
	self._coreHost = coreHost
	self.Services = coreHost.Services
	self.LoggerManager = self.Services:GetService("ILoggerManager")
	self.Logger = self.LoggerManager.GetLogger("TangSeng")
	local env: IHostingEnvironment = self.Services:GetService("IHostingEnvironment")
	self.LuaTypeProvider = env.LuaTypeProvider
	return self
end

function Host:Start()
	print("启动唐僧主机")
	self._coreHost:Start()
	print("start22")
end

function Host:Stop()
	-- 实现结束逻辑
	self._coreHost:Stop()
end

function Host:Dispose()
	self._coreHost:Dispose()
end

return Host
